package mz.co.aprendaacodar.course.entity;
import jakarta.persistence.*;import mz.co.aprendaacodar.common.entity.BaseEntity;
@Entity @Table(name="course_modules") public class CourseModule extends BaseEntity {@ManyToOne(optional=false,fetch=FetchType.LAZY) private Course course;@Column(nullable=false,length=180) private String title;@Column(columnDefinition="TEXT") private String description;@Column(nullable=false) private int position;protected CourseModule(){}public CourseModule(Course c,String t,String d,int p){course=c;title=t;description=d;position=p;}public Course getCourse(){return course;}public String getTitle(){return title;}public String getDescription(){return description;}public int getPosition(){return position;}public void update(String t,String d,int p){title=t;description=d;position=p;}public void setPosition(int p){position=p;}}
